'use client'

import { Button } from '@/components/ui/button'
import { OutfitProductList } from './OutfitProductList'
import { StickyPurchaseSection } from './StickyPurchaseSection'
import { SimilarOutfits } from './SimilarOutfits'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import type { Outfit, Product } from '@/lib/types'
import { ArrowLeft } from 'lucide-react'

interface OutfitDetailProps {
  outfit: Outfit
  similarOutfits?: Outfit[]
  onBack: () => void
  onBuyProduct: (product: Product) => void
  onBuyAll: () => void
  onSelectSimilar?: (outfit: Outfit) => void
}

export function OutfitDetail({
  outfit,
  similarOutfits = [],
  onBack,
  onBuyProduct,
  onBuyAll,
  onSelectSimilar
}: OutfitDetailProps) {
  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  if (!outfit) return null

  return (
    <div className="h-full flex flex-col">
      {/* Header with back button and resize controls */}
      <div className="border-b px-4 py-3">
        <div className="flex items-center justify-between mb-2">
          <Button
            variant="ghost"
            onClick={onBack}
            className="-ml-2"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Explore more outfits
          </Button>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      </div>

      {/* Scrollable content */}
      <div className="flex-1 overflow-y-auto">
        <div className="p-4">
          {/* Outfit title and occasion */}
          <h2 className="text-lg font-bold mb-1 text-foreground">{outfit.title}</h2>
          <p className="text-xs text-gray-600 dark:text-gray-400 mb-4">
            {outfit.description || 'Office wear'}
          </p>

          {/* Outfit preview image - prioritize flat-lay images from chat */}
          <div className="aspect-[3/4] bg-gray-100 rounded-lg mb-4 overflow-hidden">
            {(outfit.flatLayImageUrl || outfit.flatLayImageBase64 || outfit.imageUrl) ? (
              <img
                src={outfit.flatLayImageUrl || outfit.flatLayImageBase64 || outfit.imageUrl}
                alt={outfit.title}
                className={`w-full h-full ${outfit.flatLayImageUrl || outfit.flatLayImageBase64 ? 'object-contain' : 'object-cover'}`}
              />
            ) : (
              <div className="w-full h-full bg-gray-300" />
            )}
          </div>

          {/* Product list */}
          <OutfitProductList
            products={outfit.items}
            onBuyProduct={onBuyProduct}
          />

          {/* Similar outfits */}
          {onSelectSimilar && (
            <SimilarOutfits
              outfits={similarOutfits}
              onSelectOutfit={onSelectSimilar}
            />
          )}
        </div>
      </div>

      {/* Sticky purchase section */}
      <StickyPurchaseSection
        totalPrice={outfit.totalPrice}
        onBuyAll={onBuyAll}
      />
    </div>
  )
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import type { Product } from '@/lib/types'
import type { FlatLayItem, ImageGenerationResponse } from '@/lib/types/image-types'
import {
  validateProductVisualConsistency,
  validateFlatLayThumbnailMatch,
  findVisuallyConsistentReplacement,
  findReplacementsForInconsistentProducts,
  type ProductVisualConsistency,
} from '@/lib/utils/product-visual-validator'

/**
 * Cache configuration for localStorage
 */
const CACHE_PREFIX = 'flat-lay-'
const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000 // 7 days in milliseconds

/**
 * Maximum concurrent generations to prevent API overload
 * Increased from 2 to 3 for faster generation
 */
const MAX_CONCURRENT_GENERATIONS = 3
let currentGenerations = 0

/**
 * Global queue for pending generation requests
 * Module-scoped to persist across component re-renders
 */
interface QueuedRequest {
  id: string
  execute: () => void
}
const generationQueue: QueuedRequest[] = []

/**
 * Process the next item in the queue if a slot is available
 */
function processQueue(): void {
  if (currentGenerations >= MAX_CONCURRENT_GENERATIONS || generationQueue.length === 0) {
    return
  }

  const nextRequest = generationQueue.shift()
  if (nextRequest) {
    nextRequest.execute()
  }
}

/**
 * Remove a request from the queue by ID
 */
function removeFromQueue(id: string): void {
  const index = generationQueue.findIndex(req => req.id === id)
  if (index !== -1) {
    generationQueue.splice(index, 1)
  }
}

/**
 * Get queue position for a given ID (0 = not in queue, 1+ = position)
 */
function getQueuePosition(id: string): number {
  const index = generationQueue.findIndex(req => req.id === id)
  return index === -1 ? 0 : index + 1
}

interface CachedImage {
  imageBase64: string
  timestamp: number
}

interface UseFlatLayGenerationOptions {
  /** Outfit ID for caching */
  outfitId: string
  /** Products to generate flat-lay image from */
  items: Product[]
  /** Occasion context for the generation */
  occasionContext?: string
  /** Full product catalog for finding replacements (optional) */
  allProducts?: Product[]
  /** Callback when products are replaced for visual consistency */
  onProductsReplaced?: (replacements: Map<string, Product>, updatedProducts: Product[]) => void
}

interface UseFlatLayGenerationResult {
  /** Whether the image is currently being generated */
  isGenerating: boolean
  /** Whether the request is queued waiting for a slot */
  isQueued: boolean
  /** Position in the queue (0 = not queued, 1+ = position) */
  queuePosition: number
  /** Generated image as base64 data URL */
  flatLayImageBase64: string | undefined
  /** Error message if generation failed */
  error: string | undefined
  /** Trigger the flat-lay generation manually */
  generateFlatLay: () => void
  /** Whether the image was loaded from cache */
  isFromCache: boolean
  /** Map of original SKU to replacement product (for visual consistency fixes) */
  productReplacements: Map<string, Product>
  /** Products that were used for generation (with replacements applied) */
  effectiveProducts: Product[]
}

/**
 * Checks if cached image is still valid (not expired)
 */
function isCacheValid(cached: CachedImage): boolean {
  const now = Date.now()
  return now - cached.timestamp < CACHE_TTL_MS
}

/**
 * Gets cached flat-lay image from localStorage
 */
function getCachedImage(outfitId: string): string | null {
  if (typeof window === 'undefined') return null

  try {
    const key = `${CACHE_PREFIX}${outfitId}`
    const cached = localStorage.getItem(key)
    if (!cached) return null

    const parsed: CachedImage = JSON.parse(cached)
    if (isCacheValid(parsed)) {
      return parsed.imageBase64
    } else {
      // Remove expired cache
      localStorage.removeItem(key)
      return null
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error reading cache:', error)
    return null
  }
}

/**
 * Saves generated image to localStorage cache
 * Implements automatic cache eviction when quota is exceeded
 */
function setCachedImage(outfitId: string, imageBase64: string): void {
  if (typeof window === 'undefined') return

  const key = `${CACHE_PREFIX}${outfitId}`
  const cached: CachedImage = {
    imageBase64,
    timestamp: Date.now(),
  }
  const cacheValue = JSON.stringify(cached)

  // Maximum retry attempts with progressive eviction
  const maxRetries = 3
  const evictionCounts = [1, 2, Number.MAX_SAFE_INTEGER] // Evict 1, then 2, then all remaining

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      localStorage.setItem(key, cacheValue)

      // Success - log if we had to evict entries
      if (attempt > 0) {
        console.log(`[useFlatLayGeneration] Successfully cached after evicting entries (attempt ${attempt + 1})`)
      }
      return
    } catch (error) {
      // Check if this is a QuotaExceededError
      const isQuotaError =
        error instanceof DOMException &&
        (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED')

      if (isQuotaError && attempt < maxRetries) {
        // Attempt cache eviction
        const entriesToEvict = evictionCounts[attempt]
        console.warn(
          `[useFlatLayGeneration] localStorage quota exceeded. ` +
          `Attempting to evict ${entriesToEvict === Number.MAX_SAFE_INTEGER ? 'all remaining' : entriesToEvict} entries...`
        )

        const evicted = evictOldestCacheEntries(entriesToEvict)
        console.log(`[useFlatLayGeneration] Evicted ${evicted} cache entries`)

        if (evicted === 0) {
          // No cache entries to evict, image might be too large
          console.warn(
            '[useFlatLayGeneration] No cache entries available to evict. ' +
            'Image may be too large for localStorage quota.'
          )
          return
        }

        // Continue to next retry attempt
        continue
      } else {
        // Non-quota error or all retries exhausted
        if (isQuotaError) {
          console.warn(
            '[useFlatLayGeneration] Failed to cache image after all eviction attempts. ' +
            'localStorage quota cannot accommodate this image.'
          )
        } else {
          console.warn('[useFlatLayGeneration] Error saving to cache:', error)
        }
        return
      }
    }
  }
}

/**
 * Cleans up expired cache entries
 * Call this periodically to prevent localStorage bloat
 */
export function cleanupExpiredCache(): void {
  if (typeof window === 'undefined') return

  try {
    const keys: string[] = []
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        keys.push(key)
      }
    }

    for (const key of keys) {
      try {
        const cached = localStorage.getItem(key)
        if (cached) {
          const parsed: CachedImage = JSON.parse(cached)
          if (!isCacheValid(parsed)) {
            localStorage.removeItem(key)
          }
        }
      } catch {
        // Invalid cache entry, remove it
        localStorage.removeItem(key)
      }
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error cleaning cache:', error)
  }
}

/**
 * Evicts oldest cache entries to free up localStorage space
 * @param count Number of entries to evict (default 1)
 * @returns Number of entries actually evicted
 */
function evictOldestCacheEntries(count: number = 1): number {
  if (typeof window === 'undefined') return 0

  try {
    // Collect all flat-lay cache entries with their timestamps
    const cacheEntries: Array<{ key: string; timestamp: number }> = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        try {
          const cached = localStorage.getItem(key)
          if (cached) {
            const parsed: CachedImage = JSON.parse(cached)
            cacheEntries.push({ key, timestamp: parsed.timestamp })
          }
        } catch {
          // Corrupted entry, add with timestamp 0 to prioritize removal
          cacheEntries.push({ key, timestamp: 0 })
        }
      }
    }

    if (cacheEntries.length === 0) {
      return 0
    }

    // Sort by timestamp (oldest first)
    cacheEntries.sort((a, b) => a.timestamp - b.timestamp)

    // Remove the specified number of oldest entries
    const toEvict = Math.min(count, cacheEntries.length)
    let evicted = 0

    for (let i = 0; i < toEvict; i++) {
      try {
        localStorage.removeItem(cacheEntries[i].key)
        evicted++
      } catch {
        // Failed to remove, continue with others
        console.warn(`[useFlatLayGeneration] Failed to evict cache entry: ${cacheEntries[i].key}`)
      }
    }

    return evicted
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error during cache eviction:', error)
    return 0
  }
}

/**
 * Result of transforming products to flat-lay items with validation
 */
interface TransformResult {
  items: FlatLayItem[]
  validationIssues: Array<{ sku: string; name: string; issues: string[] }>
  hasInconsistentItems: boolean
  /** Map of original SKU to replacement product */
  replacements: Map<string, Product>
  /** SKUs of items that couldn't be replaced */
  excludedSkus: string[]
  /** Products after replacement (these products were used for FlatLayItems) */
  effectiveProducts: Product[]
}

/**
 * Transforms Product array to FlatLayItem array for API request
 * Includes visual consistency validation to detect mismatches between
 * product descriptions and product thumbnails
 *
 * When allProducts is provided and mismatches are detected, this function
 * attempts to find visually consistent replacement products.
 *
 * @param items - Products to transform
 * @param enableValidation - Whether to run visual consistency checks (default: true)
 * @param allProducts - Full product catalog for finding replacements (optional)
 */
function transformToFlatLayItems(
  items: Product[],
  enableValidation: boolean = true,
  allProducts?: Product[]
): TransformResult {
  const validationIssues: Array<{ sku: string; name: string; issues: string[] }> = []
  let hasInconsistentItems = false
  const replacements = new Map<string, Product>()
  const excludedSkus: string[] = []

  // First pass: identify inconsistent items and find replacements if catalog provided
  let effectiveProducts: Product[] = items

  if (enableValidation && allProducts && allProducts.length > 0) {
    // Use the batch replacement function for efficiency
    const replacementResult = findReplacementsForInconsistentProducts(
      items,
      allProducts,
      { targetGender: 'women' }
    )

    effectiveProducts = replacementResult.products
    hasInconsistentItems = replacementResult.inconsistentCount > 0

    // Copy replacements to our map
    replacementResult.replacements.forEach((replacement, originalSku) => {
      replacements.set(originalSku, replacement)
    })

    // Track unreplaceable items
    excludedSkus.push(...replacementResult.unreplaceableSkus)

    // Log replacements
    if (replacements.size > 0) {
      console.log(
        `[useFlatLayGeneration] Replaced ${replacements.size} visually inconsistent products:`,
        Array.from(replacements.entries()).map(([origSku, replacement]) => ({
          originalSku: origSku,
          replacementSku: replacement.sku,
          replacementName: replacement.name,
        }))
      )
    }

    if (excludedSkus.length > 0) {
      console.warn(
        `[useFlatLayGeneration] ${excludedSkus.length} items could not be replaced (will be included but may have visual mismatch):`,
        excludedSkus
      )
    }
  }

  // Transform products to FlatLayItems (using effective products which may include replacements)
  const flatLayItems = effectiveProducts.map((item, index) => {
    const originalItem = items[index]
    const wasReplaced = originalItem && replacements.has(originalItem.sku)

    // Run visual consistency validation on the effective item
    let isVisuallyConsistent = true
    if (enableValidation) {
      const validation = validateProductVisualConsistency(item, { enableLogging: false })
      const thumbnailMatch = validateFlatLayThumbnailMatch(item, { enableLogging: false })

      if (!validation.isConsistent || !thumbnailMatch.matches) {
        isVisuallyConsistent = false
        if (!wasReplaced) {
          // Only track as issue if this item wasn't already replaced
          hasInconsistentItems = true
          validationIssues.push({
            sku: item.sku,
            name: item.name,
            issues: [
              ...validation.issues,
              ...(thumbnailMatch.reason ? [thumbnailMatch.reason] : []),
            ],
          })

          console.warn(
            `[useFlatLayGeneration] Visual mismatch detected for product "${item.name}" (${item.sku}):`,
            {
              textGender: validation.textGender,
              imageGender: validation.imageGender,
              issues: validation.issues,
              recommendation: thumbnailMatch.recommendation,
            }
          )
        }
      } else if (wasReplaced) {
        // Replacement is visually consistent - success!
        isVisuallyConsistent = true
      }
    }

    return {
      name: item.name,
      category: item.subCategory || item.category || 'clothing',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
      sku: item.sku,
      thumbnailUrl: item.imageUrl,
      isVisuallyConsistent,
    }
  })

  // Log summary if there are remaining issues after replacement attempts
  if (hasInconsistentItems && validationIssues.length > 0) {
    console.warn(
      `[useFlatLayGeneration] ${validationIssues.length} of ${items.length} items still have visual inconsistencies after replacement attempts`,
      validationIssues
    )
  }

  return {
    items: flatLayItems,
    validationIssues,
    hasInconsistentItems,
    replacements,
    excludedSkus,
    effectiveProducts,
  }
}

/**
 * Custom hook for lazy flat-lay image generation with caching
 *
 * Features:
 * - Checks localStorage cache synchronously on initial render
 * - Supports lazy loading via Intersection Observer
 * - Uses global queue system to manage concurrent generations
 * - Provides loading states, queue status, and error handling
 * - Falls back gracefully on errors
 */
export function useFlatLayGeneration({
  outfitId,
  items,
  occasionContext,
  allProducts,
  onProductsReplaced,
}: UseFlatLayGenerationOptions): UseFlatLayGenerationResult {
  // Initialize state synchronously from cache to prevent flicker
  const [flatLayImageBase64, setFlatLayImageBase64] = useState<string | undefined>(() => {
    const cached = getCachedImage(outfitId)
    return cached || undefined
  })
  const [isFromCache, setIsFromCache] = useState<boolean>(() => {
    return !!getCachedImage(outfitId)
  })
  const [isGenerating, setIsGenerating] = useState(false)
  const [isQueued, setIsQueued] = useState(false)
  const [queuePosition, setQueuePosition] = useState(0)
  const [error, setError] = useState<string | undefined>(undefined)
  const [productReplacements, setProductReplacements] = useState<Map<string, Product>>(new Map())
  const [effectiveProducts, setEffectiveProducts] = useState<Product[]>(items)

  // Track if generation has been attempted for this outfit
  const hasAttemptedRef = useRef(false)
  // Track if component is mounted
  const isMountedRef = useRef(true)
  // Track the current outfitId for cleanup
  const currentOutfitIdRef = useRef(outfitId)

  // Reset state when outfitId changes
  useEffect(() => {
    if (currentOutfitIdRef.current !== outfitId) {
      // Remove old request from queue if exists
      removeFromQueue(currentOutfitIdRef.current)

      // Check new outfit's cache
      const cached = getCachedImage(outfitId)
      if (cached) {
        setFlatLayImageBase64(cached)
        setIsFromCache(true)
        hasAttemptedRef.current = true
      } else {
        setFlatLayImageBase64(undefined)
        setIsFromCache(false)
        hasAttemptedRef.current = false
      }

      setIsGenerating(false)
      setIsQueued(false)
      setQueuePosition(0)
      setError(undefined)
      currentOutfitIdRef.current = outfitId
    }
  }, [outfitId])

  // Update queue position periodically when queued
  useEffect(() => {
    if (!isQueued) return

    const interval = setInterval(() => {
      const pos = getQueuePosition(outfitId)
      if (isMountedRef.current) {
        setQueuePosition(pos)
        if (pos === 0) {
          // No longer in queue, stop checking
          setIsQueued(false)
        }
      }
    }, 500)

    return () => clearInterval(interval)
  }, [isQueued, outfitId])

  // Cleanup on unmount
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      // Remove from queue on unmount
      removeFromQueue(outfitId)
    }
  }, [outfitId])

  /**
   * Internal function to perform the actual generation
   */
  const performGeneration = useCallback(async () => {
    if (!isMountedRef.current) return

    // Mark as generating, not queued
    setIsQueued(false)
    setQueuePosition(0)
    setIsGenerating(true)
    setError(undefined)
    hasAttemptedRef.current = true
    currentGenerations++

    // Transform products to flat-lay items with visual consistency validation
    // Pass allProducts to enable automatic replacement of inconsistent items
    const transformResult = transformToFlatLayItems(items, true, allProducts)

    // Update replacement state
    setProductReplacements(transformResult.replacements)
    setEffectiveProducts(transformResult.effectiveProducts)

    // Notify parent component of replacements if callback provided
    if (transformResult.replacements.size > 0 && onProductsReplaced) {
      onProductsReplaced(transformResult.replacements, transformResult.effectiveProducts)
    }

    // Log visual consistency warnings
    if (transformResult.hasInconsistentItems && transformResult.excludedSkus.length > 0) {
      console.warn(
        '[useFlatLayGeneration] Some visual consistency issues remain after replacement attempts. ' +
        'Flat-lay image may not perfectly match product thumbnails for these items:',
        transformResult.excludedSkus
      )
    }

    // Extract just the items for the API call
    const flatLayItems = transformResult.items

    // Retry logic with exponential backoff
    const maxRetries = 1
    let lastError: string | undefined

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // Exponential backoff: 2^attempt * 1000ms
          const delay = Math.pow(2, attempt) * 1000
          await new Promise(resolve => setTimeout(resolve, delay))
        }

        const response = await fetch('/api/generate-image', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            generationType: 'flat-lay',
            flatLayItems,
            occasionContext,
          }),
        })

        const result: ImageGenerationResponse = await response.json()

        if (!isMountedRef.current) {
          currentGenerations--
          processQueue() // Allow next in queue to proceed
          return
        }

        if (result.success && result.imageBase64) {
          setFlatLayImageBase64(result.imageBase64)
          setIsFromCache(false)
          setError(undefined)
          // Cache the generated image
          setCachedImage(outfitId, result.imageBase64)
          currentGenerations--
          setIsGenerating(false)
          processQueue() // Process next in queue
          return
        } else {
          lastError = result.message || result.error || 'Generation failed'
        }
      } catch (err) {
        console.error('[useFlatLayGeneration] API error:', err)
        lastError = err instanceof Error ? err.message : 'Network error'
      }
    }

    // All retries failed
    if (isMountedRef.current) {
      setError(lastError)
      setIsGenerating(false)
    }
    currentGenerations--
    processQueue() // Process next in queue even on failure
  }, [outfitId, items, occasionContext, allProducts, onProductsReplaced])

  /**
   * Generate flat-lay image via API
   * Uses global queue for concurrency management
   */
  const generateFlatLay = useCallback(() => {
    // Skip if already attempted, generating, queued, or has image
    if (hasAttemptedRef.current || isGenerating || isQueued || flatLayImageBase64) {
      return
    }

    // Check cache again in case it was populated while not observing
    const cached = getCachedImage(outfitId)
    if (cached) {
      setFlatLayImageBase64(cached)
      setIsFromCache(true)
      hasAttemptedRef.current = true
      return
    }

    // Check concurrent generation limit
    if (currentGenerations >= MAX_CONCURRENT_GENERATIONS) {
      // Add to queue
      const queuedRequest: QueuedRequest = {
        id: outfitId,
        execute: performGeneration,
      }
      generationQueue.push(queuedRequest)
      setIsQueued(true)
      setQueuePosition(generationQueue.length)
      return
    }

    // Slot available, generate immediately
    performGeneration()
  }, [outfitId, isGenerating, isQueued, flatLayImageBase64, performGeneration])

  return {
    isGenerating,
    isQueued,
    queuePosition,
    flatLayImageBase64,
    error,
    generateFlatLay,
    isFromCache,
    productReplacements,
    effectiveProducts,
  }
}

/**
 * Hook for using Intersection Observer to trigger lazy generation
 */
export function useIntersectionObserver(
  callback: () => void,
  options?: IntersectionObserverInit
): React.RefCallback<HTMLElement> {
  const observerRef = useRef<IntersectionObserver | null>(null)
  const hasTriggeredRef = useRef(false)

  const setRef = useCallback(
    (element: HTMLElement | null) => {
      // Disconnect previous observer
      if (observerRef.current) {
        observerRef.current.disconnect()
        observerRef.current = null
      }

      // Skip if already triggered or no element
      if (hasTriggeredRef.current || !element) {
        return
      }

      observerRef.current = new IntersectionObserver(
        (entries) => {
          const [entry] = entries
          if (entry?.isIntersecting && !hasTriggeredRef.current) {
            hasTriggeredRef.current = true
            callback()
            // Disconnect after triggering
            observerRef.current?.disconnect()
          }
        },
        {
          threshold: 0.1, // Trigger when 10% visible
          ...options,
        }
      )

      observerRef.current.observe(element)
    },
    [callback, options]
  )

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      observerRef.current?.disconnect()
    }
  }, [])

  return setRef
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { ChatHeader } from './ChatHeader'
import { ChatMessage } from './ChatMessage'
import { ChatInput } from './ChatInput'
import { QuickPrompts } from './QuickPrompts'
import { OutfitRecommendationCard } from './OutfitRecommendationCard'
import { InteractiveTestMode } from './InteractiveTestMode'
import { Button } from '@/components/ui/button'
import { PanelSizeControls } from '@/components/layout/PanelSizeControls'
import { useResizablePanelContext } from '@/components/layout/ResizablePanel'
import { Beaker } from 'lucide-react'
import type { ChatMessage as ChatMessageType, Outfit, FlatLayItem, Product } from '@/lib/types'
import {
  findReplacementsForInconsistentProducts,
  validateProductVisualConsistency,
} from '@/lib/utils/product-visual-validator'
import type { TestResult } from '@/lib/types/test-types'
import { getMockOutfitResponse } from '@/lib/mock-data'
import { exportResultsBoth } from '@/lib/test-result-exporter'
import type { SessionContext } from '@/lib/types/chat-types'
import { createSessionContext } from '@/lib/utils/session-context'
import { useUserProfile } from '@/lib/hooks/useUserProfile'

interface ChatAssistantProps {
  onViewOutfit: (outfit: Outfit) => void
}

export function ChatAssistant({ onViewOutfit }: ChatAssistantProps) {
  const [messages, setMessages] = useState<ChatMessageType[]>([])
  const [isTyping, setIsTyping] = useState(false)
  const [testMode, setTestMode] = useState(false)

  // v2.0: Session context for duplicate prevention
  const [sessionContext, setSessionContext] = useState<SessionContext>(() => createSessionContext())
  const [conversationId] = useState<string>(() => `conv-${Date.now()}`)

  // v2.4: User profile for gender preference
  const { profile } = useUserProfile()

  // v3.1: Image generation state (Customer Journey Step 4)
  const [generatingImage, setGeneratingImage] = useState(false)
  const [imageGenerationError, setImageGenerationError] = useState<string | null>(null)

  // v8.0: All products for visual consistency replacement lookup
  const [allProducts, setAllProducts] = useState<Product[]>([])

  // v3.2: Initialize with Thai greeting message
  useEffect(() => {
    if (messages.length === 0) {
      const greeting: ChatMessageType = {
        id: 'greeting-initial',
        content: 'ฮ้ายฮายย👋 กำลังหาชุดไปไหนอยู่น้าา',
        sender: 'assistant',
        timestamp: new Date(),
      }
      setMessages([greeting])
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  // Get resize controls from ResizablePanel context (optional - only if in resizable panel)
  let panelWidth = 420
  let setPresetSize: ((size: number) => void) | undefined
  try {
    const context = useResizablePanelContext()
    panelWidth = context.panelWidth
    setPresetSize = context.setPresetSize
  } catch {
    // Not in a resizable panel context, that's okay
  }

  const isTestModeEnabled = process.env.NEXT_PUBLIC_ENABLE_TEST_MODE === 'true'

  /**
   * v8.0: Apply product replacements to an outfit for visual consistency
   * Creates a new outfit with items array where mismatched items are replaced
   * Recalculates totalPrice based on replacement prices
   */
  const applyProductReplacements = useCallback((
    outfit: Outfit,
    replacements: Map<string, Product>
  ): Outfit => {
    if (replacements.size === 0) return outfit

    const updatedItems = outfit.items.map(item => {
      const replacement = replacements.get(item.sku)
      return replacement || item
    })

    // Recalculate total price
    const newTotalPrice = updatedItems.reduce((sum, item) => sum + (item.price || 0), 0)

    return {
      ...outfit,
      items: updatedItems,
      totalPrice: newTotalPrice,
    }
  }, [])

  const handleTestComplete = (result: TestResult) => {
    console.log('Test completed:', result)
  }

  const handleExportResults = (results: TestResult[]) => {
    exportResultsBoth(results)
  }

  /**
   * v5.0: Generate flat-lay image for an outfit and update the message
   * v8.0: Enhanced with visual consistency validation and product replacement
   *
   * This function:
   * 1. Validates visual consistency between product text and thumbnails
   * 2. Replaces visually inconsistent products with consistent alternatives
   * 3. Generates flat-lay image using the corrected products
   * 4. Updates both the flat-lay image AND the product list in the message
   */
  const generateFlatLayForOutfit = useCallback(async (
    outfit: Outfit,
    messageId: string,
    productCatalog?: Product[]
  ) => {
    console.log(`[Chat] Generating flat-lay for outfit ${outfit.id}...`)

    // v8.0: Check for visual inconsistencies and find replacements if catalog provided
    let effectiveOutfit = outfit
    let replacementsMade = new Map<string, Product>()

    if (productCatalog && productCatalog.length > 0) {
      const replacementResult = findReplacementsForInconsistentProducts(
        outfit.items,
        productCatalog,
        { targetGender: 'women' }
      )

      if (replacementResult.replacements.size > 0) {
        console.log(
          `[Chat] Replacing ${replacementResult.replacements.size} visually inconsistent products in outfit ${outfit.id}:`,
          Array.from(replacementResult.replacements.entries()).map(([origSku, replacement]) => ({
            original: origSku,
            replacement: replacement.sku,
            name: replacement.name,
          }))
        )

        // Apply replacements to create the effective outfit
        effectiveOutfit = applyProductReplacements(outfit, replacementResult.replacements)
        replacementsMade = replacementResult.replacements

        // Update the message with corrected product list BEFORE generating flat-lay
        // This ensures the product thumbnails shown match the flat-lay image
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }

      if (replacementResult.unreplaceableSkus.length > 0) {
        console.warn(
          `[Chat] ${replacementResult.unreplaceableSkus.length} items in outfit ${outfit.id} have visual mismatches but no replacement found:`,
          replacementResult.unreplaceableSkus
        )
      }
    }

    // Extract FlatLayItem array from effective outfit items (with replacements applied)
    const flatLayItems: FlatLayItem[] = effectiveOutfit.items.slice(0, 5).map((item: Product) => ({
      name: item.name,
      category: item.subCategory || item.category || 'Item',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
    }))
    const occasionContext = outfit.description

    if (flatLayItems.length === 0) {
      console.log('[Chat] No items to generate flat-lay for')
      return
    }

    try {
      const imageResponse = await fetch('/api/generate-image', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          description: outfit.description || 'LOOKs Inspiration',
          generationType: 'flat-lay',
          flatLayItems,
          occasionContext,
        }),
      })

      const imageData = await imageResponse.json()

      if (imageData.success && (imageData.imageUrl || imageData.imageBase64)) {
        console.log(`[Chat] Flat-lay generated successfully for outfit ${outfit.id}`)

        // Update the message's outfit with the flat-lay image
        // Note: Product items were already updated above if replacements were made
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        flatLayImageUrl: imageData.imageUrl,
                        flatLayImageBase64: imageData.imageBase64,
                        isGeneratingFlatLay: false,
                        // Ensure items are the effective items (with replacements)
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      } else {
        console.error('[Chat] Flat-lay generation failed:', imageData.message)
        // Mark as not generating (will show fallback thumbnail)
        // Still apply any product replacements even if image generation failed
        setMessages((prev) =>
          prev.map((msg) => {
            if (msg.id === messageId && msg.outfits) {
              return {
                ...msg,
                outfits: msg.outfits.map((o) =>
                  o.id === outfit.id
                    ? {
                        ...o,
                        isGeneratingFlatLay: false,
                        items: effectiveOutfit.items,
                        totalPrice: effectiveOutfit.totalPrice,
                      }
                    : o
                ),
              }
            }
            return msg
          })
        )
      }
    } catch (error) {
      console.error('[Chat] Flat-lay generation error:', error)
      // Mark as not generating on error
      // Still apply any product replacements even if image generation failed
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg.id === messageId && msg.outfits) {
            return {
              ...msg,
              outfits: msg.outfits.map((o) =>
                o.id === outfit.id
                  ? {
                      ...o,
                      isGeneratingFlatLay: false,
                      items: effectiveOutfit.items,
                      totalPrice: effectiveOutfit.totalPrice,
                    }
                  : o
              ),
            }
          }
          return msg
        })
      )
    }
  }, [applyProductReplacements])

  const handleSendMessage = async (content: string) => {
    if (!content.trim()) return

    // Add user message
    const userMessage: ChatMessageType = {
      id: `user-${Date.now()}`,
      content: content.trim(),
      sender: 'user',
      timestamp: new Date(),
    }

    setMessages((prev) => [...prev, userMessage])
    setIsTyping(true)

    try {
      // Call real chat API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: content.trim(),
          conversationHistory: messages.map((msg) => ({
            role: msg.sender === 'user' ? 'user' : 'assistant',
            content: msg.content,
          })),
          sessionContext, // v2.0: Send current session context
          conversationId, // v2.0: Send conversation ID
          userPreferences: {
            gender: profile?.gender as 'men' | 'women' | undefined,
            userName: profile?.userName,
            ageRange: profile?.ageRange,
            stylePreferences: profile?.stylePreferences,
          }, // v2.5: Pass detailed profile info
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get response from chat API')
      }

      const data = await response.json()

      // v2.0: Update session context if returned
      if (data.sessionContext) {
        setSessionContext(data.sessionContext)
        console.log(`[Chat] Session updated: ${data.sessionContext.recommendedProductIds?.length || 0} total products recommended`)
      }

      // v8.0: Collect all products from outfits for visual consistency replacement lookup
      const outfitProducts: Product[] = (data.outfits || []).flatMap((o: Outfit) => o.items || [])
      if (outfitProducts.length > 0) {
        setAllProducts(prev => {
          // Merge with existing products, avoiding duplicates by SKU
          const existingSkus = new Set(prev.map(p => p.sku))
          const newProducts = outfitProducts.filter((p: Product) => !existingSkus.has(p.sku))
          return [...prev, ...newProducts]
        })
      }

      // v5.0: Mark outfits as generating flat-lay if we have image request
      const outfitsWithLoading = (data.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: data.imageRequest && outfit.items.length > 0,
      }))

      // Create AI response message
      const messageId = `ai-${Date.now()}`
      const aiResponse: ChatMessageType = {
        id: messageId,
        content: data.message || 'สวัสดีค่ะ! นี่คือคำแนะนำสำหรับคุณ',
        sender: 'assistant',
        timestamp: new Date(),
        outfits: outfitsWithLoading,
      }

      setMessages((prev) => [...prev, aiResponse])
      setIsTyping(false)

      // v5.0: Generate flat-lay images for each outfit (embedded in card, no separate message)
      if (data.imageRequest && outfitsWithLoading.length > 0) {
        console.log('[Chat] Image request detected, generating flat-lay for outfit cards...')

        // Add AI acknowledgment message for generation
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        // Generate flat-lay for each outfit, passing allProducts for visual consistency replacement
        for (const outfit of outfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    } catch (error) {
      console.error('Chat error:', error)

      // Fallback to mock response on error
      const aiResponse = getMockOutfitResponse(content)
      const messageId = `ai-mock-${Date.now()}`

      // v5.0: Mark mock outfits as generating flat-lay
      const mockOutfitsWithLoading = (aiResponse.outfits || []).map((outfit: Outfit) => ({
        ...outfit,
        isGeneratingFlatLay: outfit.items.length > 0,
      }))

      const mockMessage: ChatMessageType = {
        ...aiResponse,
        id: messageId,
        outfits: mockOutfitsWithLoading,
      }

      setMessages((prev) => [...prev, mockMessage])
      setIsTyping(false)

      // v5.0: Auto-generate flat-lay for mock responses
      if (mockOutfitsWithLoading.length > 0) {
        console.log('[Chat] Fallback: Auto-generating flat-lay for mock response...')

        // Add acknowledgement
        const acknowledgmentMessage: ChatMessageType = {
          id: `ai-ack-${Date.now()}`,
          content: 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨',
          sender: 'assistant',
          timestamp: new Date(),
        }
        setMessages((prev) => [...prev, acknowledgmentMessage])

        setGeneratingImage(true)
        setImageGenerationError(null)

        for (const outfit of mockOutfitsWithLoading) {
          if (outfit.items.length > 0) {
            await generateFlatLayForOutfit(outfit, messageId, allProducts)
          }
        }

        // Remove the acknowledgment message now that flat-lay images are shown in cards
        setMessages((prev) => prev.filter((msg) =>
          msg.content !== 'กำลังสร้างภาพ LOOKs จากสินค้าที่แนะนำสักครู่นะคะ... 🎨'
        ))

        setGeneratingImage(false)
      }
    }
  }

  return (
    <div className="h-full flex flex-col">
      {/* Test Mode Header */}
      {isTestModeEnabled && (
        <div className={`border-b px-4 py-3 flex items-center justify-between ${testMode ? 'bg-orange-50' : ''}`}>
          <div className="flex items-center gap-2">
            {testMode && (
              <span className="px-3 py-1 bg-orange-500 text-white font-bold rounded-md text-sm flex items-center gap-1">
                <Beaker className="w-4 h-4" />
                TEST MODE
              </span>
            )}
            <span className="text-sm text-muted-foreground">
              {testMode ? 'LLM Model Testing Interface' : 'OOTDay Stylist'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
            <Button
              size="sm"
              variant={testMode ? "primary" : "outline"}
              onClick={() => setTestMode(!testMode)}
              className={testMode ? "bg-orange-600 hover:bg-orange-700" : ""}
            >
              <Beaker className="w-4 h-4 mr-2" />
              {testMode ? 'Exit Test Mode' : 'Test Mode'}
            </Button>
          </div>
        </div>
      )}

      {/* Regular Header with resize controls */}
      {!isTestModeEnabled && !testMode && (
        <div className="border-b px-4 py-3 flex items-center justify-between">
          <span className="text-sm font-medium">OOTDay Stylist</span>
          {setPresetSize && <PanelSizeControls currentWidth={panelWidth} onSizeChange={setPresetSize} />}
        </div>
      )}

      {/* Interactive Test Mode - Full Screen */}
      {testMode && isTestModeEnabled && (
        <div className="flex-1 overflow-hidden">
          <InteractiveTestMode onExport={handleExportResults} />
        </div>
      )}

      {!testMode && <ChatHeader />}

      {/* Messages Area */}
      {!testMode && (
        <div className="flex-1 overflow-y-auto px-4 py-3">
          {messages.length === 0 && (
            <div className="text-center py-8">
              <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                สวัสดีค่ะ! OOTDay Stylist พร้อมช่วยหาลุคที่ใช่สำหรับคุณค่ะ ✨
              </p>
            </div>
          )}

          {messages.map((message) => (
            <div key={message.id}>
              <ChatMessage message={message} />

              {/* Outfit recommendations with embedded flat-lay images */}
              {message.outfits && message.outfits.length > 0 && (
                <div className="ml-10 mt-2 space-y-2">
                  {message.outfits.map((outfit) => (
                    <OutfitRecommendationCard
                      key={outfit.id}
                      outfit={outfit}
                      onViewOutfit={onViewOutfit}
                    />
                  ))}
                </div>
              )}
            </div>
          ))}

          {isTyping && (
            <div className="flex justify-start">
              <div className="flex items-center gap-2 bg-gray-100 rounded-lg px-3 py-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                  <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Quick Prompts */}
      {!testMode && <QuickPrompts onPromptClick={handleSendMessage} />}

      {/* Chat Input */}
      {!testMode && <ChatInput onSend={handleSendMessage} disabled={isTyping} />}
    </div>
  )
}

// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Re-export FlatLayItem from image-types for use in ChatMessage
import type { FlatLayItem } from './types/image-types'
export type { FlatLayItem }

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
  /** Flat-lay image URL for outfit visualization (v5.0) */
  flatLayImageUrl?: string
  /** Flat-lay image as base64 fallback (v5.0) */
  flatLayImageBase64?: string
  /** Flag indicating flat-lay image is being generated (v5.0) */
  isGeneratingFlatLay?: boolean
  /** Try-on image URL for fitting model visualization (v6.0) */
  tryOnImageUrl?: string
  /** Try-on image as base64 fallback (v6.0) */
  tryOnImageBase64?: string
  /** Flag indicating try-on image is being generated (v6.0) */
  isGeneratingTryOn?: boolean
  /** Pinterest 2026 aesthetic category (v7.0) */
  aesthetic?: import('./types/enums').AestheticCategory
  /** Trending color palette (v7.0) */
  colorPalette?: import('./types/enums').ColorPalette
  /** Layering style (v7.0) */
  layeringStyle?: import('./types/enums').LayeringStyle
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
  subCategory?: string // "Blazer", "Skirt", "Pants", etc.
  visualDescription?: string // For AI Image Generation prompt
  occasion?: string[] // For filtering
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
  /** Image display mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) (v4.0) */
  displayMode?: 'portrait' | 'flat-lay'
  /** Recommended items for flat-lay display (v4.0) */
  recommendedItems?: FlatLayItem[]
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}

/**
 * Product Visual Validator
 *
 * Validates visual consistency between product data (name, description)
 * and product images (imageUrl, thumbnailUrl) to prevent mismatches
 * in flat-lay image generation and product list display.
 *
 * The primary issue: AI-generated flat-lay images may show feminine items
 * based on text descriptions, but the product thumbnails from the catalog
 * may show masculine items (e.g., "Formal Heels" but oxford shoe thumbnail).
 *
 * This validator detects such inconsistencies and provides strategies
 * for handling them.
 */

import type { Product } from '../types'

/**
 * Visual gender category for product classification
 */
export type VisualGenderCategory = 'masculine' | 'feminine' | 'neutral'

/**
 * Result of visual consistency validation
 */
export interface ProductVisualConsistency {
  /** Whether the product's visual elements are consistent */
  isConsistent: boolean
  /** List of detected issues */
  issues: string[]
  /** Inferred gender category from product text */
  textGender: VisualGenderCategory
  /** Inferred gender category from image URL patterns */
  imageGender: VisualGenderCategory
  /** Confidence score (0-1) for the assessment */
  confidence: number
}

/**
 * Configuration for visual validation
 */
export interface VisualValidationConfig {
  /** Whether to log validation results to console */
  enableLogging?: boolean
  /** Strictness level for validation (higher = more strict) */
  strictnessLevel?: 1 | 2 | 3
}

// Default configuration
const DEFAULT_CONFIG: VisualValidationConfig = {
  enableLogging: process.env.NODE_ENV === 'development',
  strictnessLevel: 2,
}

/**
 * Masculine footwear patterns in image URLs
 */
const MASCULINE_IMAGE_PATTERNS = [
  /\/oxford/i,
  /\/derby/i,
  /\/brogue/i,
  /\/wingtip/i,
  /\/men[_-]?shoe/i,
  /\/men[_-]?dress/i,
  /\/men[_-]?loafer/i,
  /\/men[_-]?boot/i,
  /\/monk[_-]?strap/i,
  /\/cap[_-]?toe/i,
  /\/dress[_-]?shoe[_-]?m/i, // dress-shoe-m for men
  /_m_/i, // common pattern for men's items
  /-m-/i,
  /[_-]mens?[_-]/i,
]

/**
 * Feminine footwear patterns in image URLs
 */
const FEMININE_IMAGE_PATTERNS = [
  /\/heel/i,
  /\/pump/i,
  /\/stiletto/i,
  /\/mule/i,
  /\/slingback/i,
  /\/ballet/i,
  /\/flat[_-]?shoe/i,
  /\/women[_-]?shoe/i,
  /\/women[_-]?sandal/i,
  /\/women[_-]?boot/i,
  /\/women[_-]?loafer/i,
  /\/womens[_-]?loafer/i, // handle "womens-loafer" pattern
  /\/pointed[_-]?toe/i,
  /\/kitten[_-]?heel/i,
  /\/block[_-]?heel/i,
  /\/wedge/i,
  /\/espadrille/i,
  /[_-]womens?[_-]/i,
  /womens-/i, // handle "womens-" prefix
  /_w_/i, // common pattern for women's items
  /-w-/i,
]

/**
 * Masculine keywords in product text (name, description)
 */
const MASCULINE_TEXT_KEYWORDS = [
  'oxford shoe',
  'derby shoe',
  'brogue',
  'wingtip',
  "men's shoe",
  'mens shoe',
  "men's loafer",
  "men's oxford",
  "men's derby",
  "men's boot",
  'monk strap',
  'cap toe dress',
  'formal men',
]

/**
 * Feminine keywords in product text (name, description)
 */
const FEMININE_TEXT_KEYWORDS = [
  'heel',
  'pump',
  'stiletto',
  'mule',
  'slingback',
  'ballet flat',
  "women's shoe",
  'womens shoe',
  "women's loafer",
  "women's sandal",
  "women's boot",
  'pointed toe',
  'kitten heel',
  'block heel',
  'wedge',
  'espadrille',
  'ankle boot',
  'knee boot',
  'peep toe',
]

/**
 * Detect visual gender category from image URL patterns
 */
export function getImageGenderCategory(imageUrl: string | undefined): VisualGenderCategory {
  if (!imageUrl) return 'neutral'

  const url = imageUrl.toLowerCase()

  // Check for masculine patterns
  const hasMasculinePattern = MASCULINE_IMAGE_PATTERNS.some((pattern) => pattern.test(url))

  // Check for feminine patterns
  const hasFemininePattern = FEMININE_IMAGE_PATTERNS.some((pattern) => pattern.test(url))

  if (hasMasculinePattern && !hasFemininePattern) return 'masculine'
  if (hasFemininePattern && !hasMasculinePattern) return 'feminine'
  if (hasMasculinePattern && hasFemininePattern) return 'neutral' // Conflicting signals

  return 'neutral'
}

/**
 * Detect visual gender category from product text (name, description)
 */
export function getTextGenderCategory(product: Product): VisualGenderCategory {
  const combined = `${product.name || ''} ${product.visualDescription || ''} ${product.subCategory || ''}`.toLowerCase()

  // Check for masculine keywords
  const hasMasculineText = MASCULINE_TEXT_KEYWORDS.some((keyword) => combined.includes(keyword))

  // Check for feminine keywords
  const hasFeminineText = FEMININE_TEXT_KEYWORDS.some((keyword) => combined.includes(keyword))

  if (hasMasculineText && !hasFeminineText) return 'masculine'
  if (hasFeminineText && !hasMasculineText) return 'feminine'
  if (hasMasculineText && hasFeminineText) return 'neutral' // Conflicting signals

  return 'neutral'
}

/**
 * Get overall visual gender category for a product
 * Combines text and image analysis
 */
export function getProductVisualCategory(product: Product): VisualGenderCategory {
  const textGender = getTextGenderCategory(product)
  const imageGender = getImageGenderCategory(product.imageUrl)

  // If both agree, use that
  if (textGender === imageGender) return textGender

  // If one is neutral, use the other
  if (textGender === 'neutral') return imageGender
  if (imageGender === 'neutral') return textGender

  // If they conflict, prioritize text (product name is more reliable than URL patterns)
  // But flag this as potentially inconsistent
  return textGender
}

/**
 * Validate visual consistency between product text and product image
 *
 * Returns detailed information about any mismatches detected
 */
export function validateProductVisualConsistency(
  product: Product,
  config: VisualValidationConfig = DEFAULT_CONFIG
): ProductVisualConsistency {
  const textGender = getTextGenderCategory(product)
  const imageGender = getImageGenderCategory(product.imageUrl)

  const issues: string[] = []
  let confidence = 1.0

  // Check for gender mismatch
  if (textGender !== 'neutral' && imageGender !== 'neutral' && textGender !== imageGender) {
    issues.push(
      `Gender mismatch: text suggests "${textGender}" but image URL suggests "${imageGender}"`
    )
    confidence = 0.3
  }

  // Check for specific problematic patterns
  const name = (product.name || '').toLowerCase()
  const imageUrl = (product.imageUrl || '').toLowerCase()

  // "Heels" in name but oxford/derby in image URL
  if (name.includes('heel') && (imageUrl.includes('oxford') || imageUrl.includes('derby') || imageUrl.includes('brogue'))) {
    issues.push('Product named "heels" but image URL contains masculine shoe pattern')
    confidence = 0.1
  }

  // "Formal Heels" but men's shoe in image URL
  if (name.includes('formal') && name.includes('heel') && MASCULINE_IMAGE_PATTERNS.some((p) => p.test(imageUrl))) {
    issues.push('Formal heels product with masculine shoe image URL')
    confidence = 0.1
  }

  // Women's product with masculine image patterns
  if ((product.category?.toLowerCase().includes('women') || textGender === 'feminine') && imageGender === 'masculine') {
    issues.push('Women\'s product category but image URL suggests masculine product')
    confidence = 0.2
  }

  const isConsistent = issues.length === 0

  // Log if enabled
  if (config.enableLogging && !isConsistent) {
    console.warn(
      `[VisualValidator] Product ${product.sku}: INCONSISTENT - ${issues.join('; ')}`
    )
  } else if (config.enableLogging && config.strictnessLevel === 3) {
    console.debug(
      `[VisualValidator] Product ${product.sku}: CONSISTENT (text: ${textGender}, image: ${imageGender})`
    )
  }

  return {
    isConsistent,
    issues,
    textGender,
    imageGender,
    confidence,
  }
}

/**
 * Check if a product is suitable for inclusion in a women's outfit
 * considering visual consistency
 */
export function isVisuallyConsistentForWomen(
  product: Product,
  config: VisualValidationConfig = DEFAULT_CONFIG
): boolean {
  const validation = validateProductVisualConsistency(product, config)

  // Reject if there are gender mismatches and image suggests masculine
  if (!validation.isConsistent && validation.imageGender === 'masculine') {
    return false
  }

  // Reject if explicitly masculine
  if (validation.textGender === 'masculine' || validation.imageGender === 'masculine') {
    return false
  }

  return true
}

/**
 * Filter products to only include those with consistent visuals for women's outfits
 */
export function filterVisuallyConsistentProducts(
  products: Product[],
  targetGender: 'women' | 'men' = 'women',
  config: VisualValidationConfig = DEFAULT_CONFIG
): Product[] {
  return products.filter((product) => {
    const validation = validateProductVisualConsistency(product, config)

    if (targetGender === 'women') {
      return isVisuallyConsistentForWomen(product, config)
    } else {
      // For men's products, reject if feminine
      return validation.textGender !== 'feminine' && validation.imageGender !== 'feminine'
    }
  })
}

/**
 * Get a summary of visual consistency issues for a set of products
 * Useful for debugging and data quality reporting
 */
export function getVisualConsistencySummary(
  products: Product[],
  config: VisualValidationConfig = DEFAULT_CONFIG
): {
  total: number
  consistent: number
  inconsistent: number
  issues: Array<{ sku: string; name: string; issues: string[] }>
} {
  const results = products.map((product) => ({
    product,
    validation: validateProductVisualConsistency(product, { ...config, enableLogging: false }),
  }))

  const consistent = results.filter((r) => r.validation.isConsistent).length
  const inconsistent = results.filter((r) => !r.validation.isConsistent)

  return {
    total: products.length,
    consistent,
    inconsistent: inconsistent.length,
    issues: inconsistent.map((r) => ({
      sku: r.product.sku,
      name: r.product.name,
      issues: r.validation.issues,
    })),
  }
}

/**
 * Validate that a product's thumbnail will match the flat-lay image description
 *
 * This is the key function for preventing the mismatch issue:
 * - If the product text describes feminine footwear (heels, pumps)
 * - But the product thumbnail shows masculine footwear (oxfords, derbies)
 * - The flat-lay will show heels but the product list will show oxfords
 */
export function validateFlatLayThumbnailMatch(
  product: Product,
  config: VisualValidationConfig = DEFAULT_CONFIG
): {
  matches: boolean
  reason?: string
  recommendation?: 'include' | 'exclude' | 'replace' | 'use-text-only'
} {
  const validation = validateProductVisualConsistency(product, config)

  if (validation.isConsistent) {
    return { matches: true, recommendation: 'include' }
  }

  // Specific case: feminine text but masculine image (the main bug scenario)
  if (validation.textGender === 'feminine' && validation.imageGender === 'masculine') {
    return {
      matches: false,
      reason: `Product "${product.name}" has feminine description but masculine image`,
      recommendation: 'exclude', // Prefer finding a replacement
    }
  }

  // Specific case: masculine text but feminine image (less common)
  if (validation.textGender === 'masculine' && validation.imageGender === 'feminine') {
    return {
      matches: false,
      reason: `Product "${product.name}" has masculine description but feminine image`,
      recommendation: 'exclude',
    }
  }

  // Unknown mismatch
  return {
    matches: false,
    reason: validation.issues.join('; '),
    recommendation: 'use-text-only', // Fall back to text description in flat-lay
  }
}

/**
 * Calculate similarity score between two products for replacement ranking
 *
 * Higher score = better replacement candidate
 * Factors: category match, price proximity, occasion overlap, color compatibility
 */
export function getSimilarityScore(original: Product, candidate: Product): number {
  let score = 0

  // Category match (30 points)
  const origCategory = (original.subCategory || original.category || '').toLowerCase()
  const candCategory = (candidate.subCategory || candidate.category || '').toLowerCase()
  if (origCategory === candCategory) {
    score += 30
  } else if (origCategory.includes(candCategory) || candCategory.includes(origCategory)) {
    score += 15
  }

  // Price proximity (25 points)
  // Perfect match at same price, decreasing as price difference grows
  const priceDiff = Math.abs(original.price - candidate.price)
  const priceRatio = priceDiff / original.price
  if (priceRatio <= 0.1) {
    score += 25 // Within 10% of original price
  } else if (priceRatio <= 0.2) {
    score += 20
  } else if (priceRatio <= 0.3) {
    score += 15
  } else if (priceRatio <= 0.5) {
    score += 5
  }

  // Occasion overlap (20 points)
  const origOccasions = original.occasion || []
  const candOccasions = candidate.occasion || []
  if (origOccasions.length > 0 && candOccasions.length > 0) {
    const overlap = origOccasions.filter(o => candOccasions.includes(o)).length
    score += Math.min(20, overlap * 10)
  } else if (origOccasions.length === 0 && candOccasions.length === 0) {
    score += 10 // Both have no occasion specified, neutral match
  }

  // Color compatibility (15 points)
  const origColors = original.colors || []
  const candColors = candidate.colors || []
  if (origColors.length > 0 && candColors.length > 0) {
    const colorMatch = origColors.some(c => candColors.includes(c))
    if (colorMatch) score += 15
  }

  // Brand consistency (10 points)
  if (original.brand && candidate.brand && original.brand.toLowerCase() === candidate.brand.toLowerCase()) {
    score += 10
  }

  return score
}

/**
 * Find a visually consistent replacement product when original has visual mismatch
 *
 * This function finds substitute products that:
 * 1. Have consistent visual elements (image matches text description)
 * 2. Match the original product's category
 * 3. Are within acceptable price range (±30% of original)
 * 4. Match occasion tags if present
 *
 * @param product - The original product with visual inconsistency
 * @param allProducts - Full product catalog to search for replacements
 * @param options - Optional configuration for replacement search
 * @returns Replacement product or null if none found
 */
export function findVisuallyConsistentReplacement(
  product: Product,
  allProducts: Product[],
  options: {
    priceRangeFactor?: number // Default 0.3 (30%)
    requireOccasionMatch?: boolean // Default false
    targetGender?: 'women' | 'men' // Default 'women'
    maxCandidates?: number // Max candidates to evaluate (performance)
  } = {}
): Product | null {
  const {
    priceRangeFactor = 0.3,
    requireOccasionMatch = false,
    targetGender = 'women',
    maxCandidates = 50,
  } = options

  // Calculate acceptable price range
  const minPrice = product.price * (1 - priceRangeFactor)
  const maxPrice = product.price * (1 + priceRangeFactor)

  // Get product category for matching
  const productSubCategory = (product.subCategory || '').toLowerCase()
  const productCategory = (product.category || '').toLowerCase()
  const productOccasions = product.occasion || []

  // Pre-filter candidates based on basic criteria
  const candidates = allProducts.filter(candidate => {
    // Skip same product
    if (candidate.sku === product.sku) return false

    // Skip if not in price range
    if (candidate.price < minPrice || candidate.price > maxPrice) return false

    // Must have same or similar category
    const candSubCategory = (candidate.subCategory || '').toLowerCase()
    const candCategory = (candidate.category || '').toLowerCase()
    const categoryMatch =
      candSubCategory === productSubCategory ||
      candCategory.includes(productCategory) ||
      productCategory.includes(candCategory) ||
      // Allow similar footwear categories
      (productSubCategory.includes('heel') && (candSubCategory.includes('heel') || candSubCategory.includes('pump'))) ||
      (productSubCategory.includes('pump') && (candSubCategory.includes('heel') || candSubCategory.includes('pump')))

    if (!categoryMatch) return false

    // Gender filter for women's products
    if (targetGender === 'women') {
      // Exclude products with men in category
      if (candCategory.includes('men') && !candCategory.includes('women')) return false
    }

    // Occasion match if required
    if (requireOccasionMatch && productOccasions.length > 0) {
      const candOccasions = candidate.occasion || []
      const hasOccasionOverlap = productOccasions.some(o => candOccasions.includes(o))
      if (!hasOccasionOverlap) return false
    }

    return true
  })

  // Limit candidates for performance
  const limitedCandidates = candidates.slice(0, maxCandidates)

  // Filter to visually consistent products and score them
  const scoredCandidates: Array<{ product: Product; score: number }> = []

  for (const candidate of limitedCandidates) {
    // Check visual consistency
    const isConsistent = targetGender === 'women'
      ? isVisuallyConsistentForWomen(candidate, { enableLogging: false })
      : validateProductVisualConsistency(candidate, { enableLogging: false }).isConsistent

    if (!isConsistent) continue

    // Calculate similarity score
    const score = getSimilarityScore(product, candidate)
    scoredCandidates.push({ product: candidate, score })
  }

  // Sort by score (descending) and return best match
  scoredCandidates.sort((a, b) => b.score - a.score)

  if (scoredCandidates.length > 0) {
    const best = scoredCandidates[0]
    console.log(
      `[VisualValidator] Found replacement for "${product.name}" (${product.sku}): ` +
      `"${best.product.name}" (${best.product.sku}) with score ${best.score}`
    )
    return best.product
  }

  console.log(
    `[VisualValidator] No suitable replacement found for "${product.name}" (${product.sku})`
  )
  return null
}

/**
 * Find replacements for all visually inconsistent products in an array
 *
 * @param products - Products to check and potentially replace
 * @param allProducts - Full product catalog for finding replacements
 * @param options - Configuration options
 * @returns Object with replaced products array and replacement map
 */
export function findReplacementsForInconsistentProducts(
  products: Product[],
  allProducts: Product[],
  options: {
    priceRangeFactor?: number
    requireOccasionMatch?: boolean
    targetGender?: 'women' | 'men'
  } = {}
): {
  /** Products with replacements applied where possible */
  products: Product[]
  /** Map of original SKU to replacement product (only for items that were replaced) */
  replacements: Map<string, Product>
  /** SKUs of items that had inconsistencies but couldn't be replaced */
  unreplaceableSkus: string[]
  /** Total number of items that had visual inconsistencies */
  inconsistentCount: number
} {
  const replacements = new Map<string, Product>()
  const unreplaceableSkus: string[] = []
  let inconsistentCount = 0

  const resultProducts = products.map(product => {
    const validation = validateProductVisualConsistency(product, { enableLogging: false })

    // If consistent, keep original
    if (validation.isConsistent) {
      return product
    }

    inconsistentCount++

    // Try to find replacement
    const replacement = findVisuallyConsistentReplacement(product, allProducts, options)

    if (replacement) {
      replacements.set(product.sku, replacement)
      return replacement
    }

    // No replacement found, keep original but track it
    unreplaceableSkus.push(product.sku)
    return product
  })

  return {
    products: resultProducts,
    replacements,
    unreplaceableSkus,
    inconsistentCount,
  }
}

